SELECT CASE WHEN s.rating >= 3.7 THEN 'high' WHEN s.rating >= 2.2 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(p.stock_qty) AS stock_qty_count, SUM(p.stock_qty) AS total_stock_qty FROM products p LEFT OUTER JOIN suppliers s ON p.supplier_id = s.id WHERE s.country != 'UK' GROUP BY CASE WHEN s.rating >= 3.7 THEN 'high' WHEN s.rating >= 2.2 THEN 'mid' ELSE 'low' END ORDER BY stock_qty_count;
